#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *data;
    size_t capacity;   /* maximum bytes stored (header capacity) */
    size_t head;       /* next write position */
    size_t size;       /* bytes currently in buffer */
};

ringbuf_t *rb_create(size_t capacity) {
    if (capacity == 0)
        return NULL;

    ringbuf_t *rb = (ringbuf_t *)calloc(1, sizeof(ringbuf_t));
    if (!rb)
        return NULL;

    rb->data = (uint8_t *)calloc(capacity + 1, sizeof(uint8_t));
    if (!rb->data) {
        free(rb);
        return NULL;
    }
    rb->capacity = capacity;
    rb->head = 0;
    rb->size = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb) {
    if (!rb)
        return;
    free(rb->data);
    free(rb);
}

static size_t rb_free(const ringbuf_t *rb) {
    return rb->capacity - rb->size;
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len) {
    if (!rb || !data || len == 0)
        return 0;

    size_t avail = rb_free(rb);
    if (avail == 0)
        return 0;

    size_t to_write = (len < avail) ? len : avail;

    /* Does the write span the wrap-around boundary? */
    size_t tail_room = rb->capacity - rb->head;
    if (to_write <= tail_room) {
        memcpy(rb->data + rb->head, data, to_write);
        rb->head += to_write;
    } else {
        /* first chunk */
        memcpy(rb->data + rb->head, data, tail_room);
        /* second chunk wraps */
        size_t rest = to_write - tail_room;
        memcpy(rb->data, data + tail_room, rest);
        rb->head = rest;
    }

    rb->size += to_write;
    return to_write;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len) {
    if (!rb || !out || len == 0 || rb->size == 0)
        return 0;

    size_t to_read = (len < rb->size) ? len : rb->size;
    size_t avail_at_head = rb->capacity - rb->head;

    if (to_read <= avail_at_head) {
        memcpy(out, rb->data + rb->head, to_read);
    } else {
        /* first chunk at current head */
        memcpy(out, rb->data + rb->head, avail_at_head);
        /* second chunk wraps to start */
        size_t rest = to_read - avail_at_head;
        memcpy(out + avail_at_head, rb->data, rest);
    }

    rb->head = (rb->head + to_read) % rb->capacity;
    rb->size -= to_read;
    return to_read;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len) {
    if (!rb || !out || len == 0 || rb->size == 0)
        return 0;

    size_t to_read = (len < rb->size) ? len : rb->size;
    size_t avail_at_head = rb->capacity - rb->head;

    if (to_read <= avail_at_head) {
        memcpy(out, rb->data + rb->head, to_read);
    } else {
        memcpy(out, rb->data + rb->head, avail_at_head);
        size_t rest = to_read - avail_at_head;
        memcpy(out + avail_at_head, rb->data, rest);
    }

    return to_read;
}

size_t rb_size(const ringbuf_t *rb) {
    if (!rb)
        return 0;
    return rb->size;
}

size_t rb_capacity(const ringbuf_t *rb) {
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb) {
    if (!rb)
        return;
    rb->head = 0;
    rb->size = 0;
}

/* --- small test --- */
#define TEST(name) static void name(void)
#define RUN(name) do { name(); printf("  PASS: %s\n", #name); } while(0)

#include <stdio.h>

TEST(create_destroy) {
    ringbuf_t *rb = rb_create(16);
    if (!rb) { puts("FAIL"); return; }
    if (rb_capacity(rb) != 16) { puts("FAIL"); return; }
    if (rb_size(rb) != 0) { puts("FAIL"); return; }

    const uint8_t msg[] = "hello";
    size_t n = rb_write(rb, msg, sizeof(msg)); /* includes NUL */
    if (n != sizeof(msg)) { puts("FAIL"); return; }
    if (rb_size(rb) != sizeof(msg)) { puts("FAIL"); return; }

    uint8_t buf[16];
    size_t m = rb_read(rb, buf, sizeof(buf));
    if (m != sizeof(msg)) { puts("FAIL"); return; }
    if (memcmp(buf, msg, sizeof(msg)) != 0) { puts("FAIL"); return; }

    rb_destroy(rb);
    rb_destroy(NULL); /* must not crash */
}

TEST(wrap_read) {
    ringbuf_t *rb = rb_create(8);
    const uint8_t a[] = {1,2,3,4,5};
    const uint8_t b[] = {6,7,8,9,10};
    rb_write(rb, a, sizeof(a));
    uint8_t tmp;
    rb_read(rb, &tmp, 3);       /* drain 3 at head */
    rb_write(rb, b, sizeof(b));  /* wraps around ring */
    uint8_t out[10];
    size_t n = rb_read(rb, out, 10);
    if (n != 7) { puts("FAIL"); return; }
    for (int i = 0; i < 4; i++) if (out[i] != (uint8_t)(i + 4)) { puts("FAIL"); return; }
    for (int i = 0; i < 3; i++) if (out[4+i] != (uint8_t)(i + 7)) { puts("FAIL"); return; }

    /* peek doesn't consume */
    uint8_t p;
    rb_peek(rb, &p, 1);
    if (p != 8) { puts("FAIL"); return; }
    if (rb_size(rb) != 7) { puts("FAIL"); return; } /* size unchanged */

    rb_destroy(rb);
}

TEST(clear) {
    ringbuf_t *rb = rb_create(4);
    const uint8_t d[] = {1,2};
    rb_write(rb, d, sizeof(d));
    if (rb_size(rb) != 2) { puts("FAIL"); return; }
    rb_clear(rb);
    if (rb_size(rb) != 0) { puts("FAIL"); return; }

    /* can write to cleared buffer */
    const uint8_t e[] = {9};
    if (rb_write(rb, e, sizeof(e)) != 1) { puts("FAIL"); return; }
    rb_destroy(rb);
}

TEST(null_ops) {
    if (rb_create(0) != NULL) { puts("FAIL"); return; }
    if (rb_size(NULL) != 0) { puts("FAIL"); return; }
    if (rb_capacity(NULL) != 0) { puts("FAIL"); return; }

    ringbuf_t *empty = rb_create(2);
    uint8_t d1[] = {1,2}, o[4];
    if (rb_write(empty, NULL, 2) != 0) { puts("FAIL"); return; }
    if (rb_read(empty, NULL, 2) != 0) { puts("FAIL"); return; }
    if (rb_peek(empty, NULL, 1) != 0) { puts("FAIL"); return; }

    /* full buffer cannot accept more */
    rb_write(empty, d1, sizeof(d1));
    if (rb_write(empty, d1, sizeof(d1)) != 0) { puts("FAIL"); return; }

    rb_destroy(empty);
}

TEST(partial_write_full_fit) {
    ringbuf_t *rb = rb_create(4);
    const uint8_t big[] = "hello world";
    size_t n = rb_write(rb, big, sizeof(big));
    if (n != 4) { puts("FAIL"); return; }
    /* wrapped write: 3 bytes tail + 1 byte head */
    uint8_t out[4];
    size_t m = rb_read(rb, out, 4);
    if (m != 4 || memcmp(out, big, 4) != 0) { puts("FAIL"); return; }
    rb_destroy(rb);
}

int main(void) {
    printf("[ringbuf tests]\n");
    RUN(create_destroy);
    RUN(wrap_read);
    RUN(clear);
    RUN(null_ops);
    RUN(partial_write_full_fit);
    printf("All passed.\n");
    return 0;
}

#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

/* ---- internal struct (opaque to callers) ---- */
struct ringbuf {
    uint8_t *data;
    size_t capacity;     /* buffer length passed to rb_create()        */
    size_t head;         /* index of the oldest byte (first read pos)   */
    size_t size;         /* bytes currently stored (0 .. capacity)      */
};

/* helpers --------------------------------------------------------------- */
static inline size_t free_space(const ringbuf_t *rb) { return rb->capacity - rb->size; }

/* ---- public API (specification) ------------------------------------- */

ringbuf_t *rb_create(size_t capacity)
{
    if (capacity == 0)
        return NULL;

    ringbuf_t *rb = (ringbuf_t *)calloc(1, sizeof *rb);
    if (!rb)
        return NULL;

    rb->data = (uint8_t *)calloc(capacity + 1u, sizeof(uint8_t));   /* extra guard byte */
    if (!rb->data) { free(rb); return NULL; }

    rb->capacity = capacity;
    rb->head     = 0;
    rb->size     = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)      /* tolerates NULL */
{
    if (!rb) return;
    free(rb->data);
    free(rb);
}

/* Write: appends from *data up to *len* bytes.  Returns how many were
   actually stored (never more than would overflow the ring).            */
size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data || len == 0) return 0;

    size_t free  = free_space(rb);
    if (free == 0)                 return 0;

    size_t n   = (len < free) ? len : free;      /* cap at available */
    size_t tail = rb->capacity - rb->head;         /* bytes from head→end */

    if (n <= tail) {
        /* fits in the tail segment — no wrap */
        memcpy(rb->data + rb->head, data, n);
        rb->head += n;
    } else {
        /* spans the boundary: first chunk fills the tail              */
        memcpy(rb->data + rb->head, data, tail);
        /* second chunk wraps to the start                             */
        size_t rest = n - tail;
        memcpy(rb->data, data + tail, rest);
        rb->head    = rest;
    }
    rb->size += n;
    return n;
}

/* Read: removes oldest *len* bytes into *out*.  Returns how many were
   actually read (bounded by available data).                            */
size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0 || rb->size == 0) return 0;

    size_t n   = (len < rb->size) ? len : rb->size;
    size_t avail = rb->capacity - rb->head;      /* bytes from head→end */

    if (n <= avail) {
        memcpy(out, rb->data + rb->head, n);
    } else {
        memcpy(out, rb->data + rb->head, avail);
        size_t rest = n - avail;
        memcpy(out + avail, rb->data, rest);
    }

    rb->head    = (rb->head + n) % rb->capacity; /* advance head  */
    rb->size   -= n;
    return n;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0 || rb->size == 0) return 0;

    size_t n   = (len < rb->size) ? len : rb->size;
    size_t avail = rb->capacity - rb->head;

    if (n <= avail) {
        memcpy(out, rb->data + rb->head, n);
    } else {
        memcpy(out, rb->data + rb->head, avail);
        size_t rest = n - avail;
        memcpy(out + avail, rb->data, rest);
    }

    /* head is NOT advanced */
    return n;
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb) return 0;
    return rb->size;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb) return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)   /* drops all content               */
{
    if (!rb) return;
    rb->head = 0;
    rb->size = 0;
}


/* ---- smoke tests (self-contained, no harness needed) ----------------- */
#include <stdio.h>

#define CHECK(cond, msg)                                               \
    do {                                                               \
        if (!(cond)) { fprintf(stderr, "FAIL %s at line %d\n", msg, __LINE__); return 1; } \
    } while(0)

int main(void)
{
    printf("[ ringbuf smoke tests ]\n");

    /* 1. create / capacity / destroy-NULL -------------------------- */
    {
        ringbuf_t *rb = rb_create(16); CHECK(rb != NULL, "create");
        CHECK(rb_capacity(rb) == 16,   "capacity");
        CHECK(rb_size(rb)     == 0,    "initial size");

        rb_destroy(NULL);   /* must not crash */
        rb_destroy(rb);
    }

    /* 2. invalid capacity ------------------------------------------ */
    { ringbuf_t *rb = rb_create(0); CHECK(rb == NULL, "zero-capacity"); }

    /* 3. basic write / read round-trip (no-wrap) ------------------- */
    {
        ringbuf_t *rb = rb_create(8);
        const uint8_t msg[] = "ab";
        CHECK(rb_write(rb, msg, sizeof(msg)) == 2, "write");
        CHECK(rb_size(rb)             == 2,     "size-after-write");

        uint8_t out[16]; memset(out, 0xAA, sizeof(out));
        CHECK(rb_read(rb, out, sizeof(out)) ==  2, "read");
        CHECK(out[0] == 'a' && out[1] == 'b',     "data");
        CHECK(out[2] == 0xAA,                       "pad-not-touched");
        rb_destroy(rb);
    }

    /* 4. wrap-around write ----------------------------------------- */
    {
        ringbuf_t *rb = rb_create(4);
        const uint8_t a[] = {'1','2','3'};   /* fills 3 / 4 slots */
        CHECK(rb_write(rb, a, sizeof(a)) ==                  3, "w1");

        /* drain one at head, then write more → ring wrap          */
        { uint8_t dummy; rb_read(rb, &dummy, 1); }     /* size→3  head→1 */
        const uint8_t b[] = {'X','Y','Z','W'};          /* len=4, free=1 */
        CHECK(rb_write(rb, b, sizeof(b)) ==                  1, "w2-fit");

        /* peek (does not consume) ----------------- ---------- ------- */
        { uint8_t p; size_t k;
          k = rb_peek(rb, &p, 1);
          CHECK(k == 1 && p == '2',     "peek");
          CHECK(rb_size(rb)              == 3,    "size-unchanged"); }

        rb_destroy(rb);
    }

    /* 5. partial-write (data larger than ring) --------------------- */
    {
        ringbuf_t *rb = rb_create(4);
        const uint8_t big[] = {'a','b','c','d','e'};
        CHECK(rb_write(rb, big, sizeof(big)) ==                  4, "partial-w");

        /* read it back — tail then wrapped head */
        uint8_t out[16]; memset(out, 0xBB, sizeof(out));
        CHECK(rb_read(rb, out, sizeof(out))   ==                  4, "read-all");
        CHECK(memcmp(out, big, 4) ==                               0, "data-correct");
        rb_destroy(rb);
    }

    /* 6. clear / re-use ------------------------------------------------ */
    {
        ringbuf_t *rb = rb_create(4);
        const uint8_t d[] = {'?'};   CHECK(rb_write(rb, d,1) ==1,"w");
        rb_clear(rb);
        CHECK(rb_size(rb)               ==              0 ,     "cleared");
        /* re-writing after clear must work */
        CHECK(rb_write(rb, d, sizeof(d)) == 1,                "re-write");
        rb_destroy(rb);
    }

    /* 7. NULL-args safety ------------------------------------------ */
    {
        ringbuf_t *rb = rb_create(2);
        CHECK(rb_write(rb, NULL,        2) ==       0 ,     "");
        CHECK(rb_read (rb,           (uint8_t*)0x1,   2) ==       0 ,     "" );

        /* full → write returns 0 */
        const uint8_t x[] = {9,9}; CHECK(rb_write(rb,x,sizeof(x))==2,"fill");
        CHECK(rb_write(rb,x,1)          ==       0 ,     "full");

        rb_destroy(rb);
    }

    printf("All tests passed.\n");
    return 0;
}

