    size_t n   = (len < rb->cnt) ? len : rb->cnt;  /* clamp at available */
    size_t avail = rb->capacity - rb->head;          /* head → end-of-array */

    if (n <= avail) {
        memcpy(out, rb->data + rb->head, n);
