        /* spans the boundary */
        memcpy(out, rb->data + rb->head, avail);
        size_t rest = n - avail;
        memcpy(out + avail, rb->data, rest);
    }

    rb->head = (rb->head + n) % rb->capacity;
    rb->cnt -= n;
    return n;
}

